import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 4 Seeing hands","description":"学习 报告动词与认知距离，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 4 Seeing hands","description":"学习 报告动词与认知距离，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 报告动词与认知距离，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 3 Matterhorn man","link":"/life/english/new-concept/book-4/unit-01/lesson-003"},"next":{"text":"第四册：流利英语 · Lesson 5 Youth","link":"/life/english/new-concept/book-4/unit-01/lesson-005"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 3 Matterhorn man","link":"/life/english/new-concept/book-4/unit-01/lesson-003"},"next":{"text":"第四册：流利英语 · Lesson 5 Youth","link":"/life/english/new-concept/book-4/unit-01/lesson-005"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-01/lesson-004.md","filePath":"life/english/new-concept/book-4/unit-01/lesson-004.md"}'),i={name:"life/english/new-concept/book-4/unit-01/lesson-004.md"};function l(r,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-4-seeing-hands" tabindex="-1">第四册：流利英语 · Lesson 4 Seeing hands <a class="header-anchor" href="#第四册-流利英语-·-lesson-4-seeing-hands" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 4 Seeing hands&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>把本课作为历史阅读材料：作者记录的异常感知主张不应直接当作已确立的科学事实。训练区分“有人声称”“某研究报告”与“已经被可靠重复验证”，讨论遮蔽、对照、重复实验等证据要求。学习保留报告来源，同时明确说明材料的年代与验证边界。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>claim</td><td>/kleɪm/</td><td>n./v.</td><td>主张；声称</td><td>test a claim</td></tr><tr><td>replicate</td><td>/ˈreplɪkeɪt/</td><td>v.</td><td>重复验证</td><td>replicate a result</td></tr><tr><td>control</td><td>/kənˈtrəʊl/</td><td>n.</td><td>对照条件</td><td>a control condition</td></tr><tr><td>blindfold</td><td>/ˈblaɪndfəʊld/</td><td>n.</td><td>眼罩</td><td>wear a blindfold</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>be reported to — 据报告，保留消息来源</li><li>rule out — 排除一种可能解释</li></ul><h2 id="语法讲解-报告动词与认知距离" tabindex="-1">语法讲解：报告动词与认知距离 <a class="header-anchor" href="#语法讲解-报告动词与认知距离" aria-label="Permalink to &quot;语法讲解：报告动词与认知距离&quot;">​</a></h2><p>claim that 表示提出主张，不表示说话者认可主张；report that 表示报告内容，其可靠性仍需评估。be said to 和 be reported to 将信息归于他人，可接 to have done 表示更早发生的动作。写历史科学材料时，不能把 is claimed to 改写成 can 而保持相同证据强度。实验主张应区分来源、方法、结果和可重复性；语法上的被动结构本身不增加可信度。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The participant was reported to have identified the colour, but the test did not rule out visual cues.</p></blockquote><p>据报告参与者辨认出了颜色，但实验没有排除视觉线索。</p><p>was reported to 标示二手报告；to have identified 表辨认早于报告；but 引出方法限制。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>“was reported to identify”不是“被证实能够辨认”；reported 与 proved 的证据含义不同。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读时重读 claims、does not、independent；请同伴只根据你的朗读判断你是在报告主张还是确认事实。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The report claims that a volunteer identified several colours while blindfolded. It does not describe how visual cues were excluded. Independent teams would need to repeat the test under controlled conditions.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句评价一项“蒙眼认色”报道：归属主张、指出缺失条件、提出验证方式。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>三句分别承担归属、方法审查和验证要求，不把异常主张当作既定事实。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>将“研究人员声称结果可重复”译为英语，使用 claim。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The researchers claim that the result can be replicated.</p><p><strong>解析：</strong> claim that 引出主张而不替读者保证其真实。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例排除视觉线索了吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> did not rule out 明确表示未排除。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：She is said to ___ completed the test yesterday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 过去事件使用 to have completed。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：报告动词与认知距离。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-003">上一课</a> · <a href="/life/english/new-concept/book-4/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-01/lesson-005">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
